package com.example

import com.example.ExamQuestionHelper.QSpec

internal object ScienceLiveExamGeneticsEcoBank1 {
  private const val T = "ප්‍රවේණිය, ක්ෂුද්‍රජීවීන් හා පරිසර විද්‍යාව"

  private fun q(
    stem: String,
    c: String,
    d1: String,
    d2: String,
    d3: String,
    exp: String = "ප්‍රවේණිය හා පරිසර විද්‍යාවට අදාළ නිවැරදි කරුණකි."
  ) = QSpec(T, stem, c, listOf(d1, d2, d3), exp)

  fun questions(): List<QSpec> = listOf(
    q("ප්‍රවේණි විද්‍යාවේ පියා ලෙස හඳුන්වනු ලබන, ගෙවතු මෑ ශාකය යොදා පරීක්ෂණ කළ විද්‍යාඥයා කවුද?", "ග්‍රෙගර් මෙන්ඩල්", "චාල්ස් ඩාවින්", "ලුවී පාස්චර්", "ඇලෙක්සැන්ඩර් ෆ්ලෙමින්", "ග්‍රෙගර් මෙන්ඩල් ප්‍රවේණියේ මූලික නියම සොයා ගත්තේය."),
    q("විරුද්ධ ලක්ෂණ යුගලක් පමණක් සලකා සිදු කරන ඒකාංග මුහුමක F₂ පරම්පරාවේ ලැබෙන ප්‍රවේණික දර්ශීය අනුපාතය කුමක්ද?", "1:2:1", "3:1", "9:3:3:1", "1:1", "3:1 යනු F₂ පරම්පරාවේ රූපානුදර්ශී අනුපාතයයි."),
    q("ඒකාංග මුහුමකදී සමයුග්මක ප්‍රමුඛ (TT) හා සමයුග්මක නිලීන (tt) ශාක මුහුම් කළ විට F₁ පරම්පරාවේ ලැබෙන රූපානුදර්ශය කුමක්ද?", "සියල්ලම උස (Tt)", "සියල්ලම මිටි (tt)", "50% උස හා 50% මිටි", "75% උස හා 25% මිටි", "F₁ පරම්පරාවේදී ප්‍රමුඛ ඇලීලය (T) පමණක් ප්‍රකාශ වේ."),
    q("ජීවියෙකුගේ බාහිරව දිස්වන ලක්ෂණ (උදා: උස බව හෝ ඇස්වල වර්ණය) හඳුන්වන්නේ කුමන නමින්ද?", "රූපානුදර්ශය (Phenotype)", "ප්‍රවේණිදර්ශය (Genotype)", "ඇලීලය", "විකෘතිය", "රූපානුදර්ශය ප්‍රවේණිදර්ශය හා පරිසර සාධක මත රඳා පවතී."),
    q("දී ඇති ලක්ෂණයක් සඳහා එකම ආකාරයේ ඇලීල යුගලක් (TT හෝ tt) දරන ජීවියෙකු හඳුන්වන්නේ කෙසේද?", "සමයුග්මක (Homozygous)", "විෂමයුග්මක (Heterozygous)", "දෙමුහුන්", "ඒකගුණ", "Tt යනු විෂමයුග්මක තත්ත්වයයි."),
    q("මිනිසාගේ ශරීර සෛලයක ඇති වර්ණදේහ යුගල 23 න් ලිංග නිර්ණය කරන ලිංගික වර්ණදේහ යුගලය පිරිමියෙකුගේ කෙබඳුද?", "XY", "XX", "YY", "XO", "ස්ත්‍රීන්ට XX වර්ණදේහ යුගලක් ඇති බැවින් සියලු ඩිම්බවල X අඩංගු වේ."),
    q("මිනිස් දරුවෙකු පුතෙකු හෝ දුවකු වීම තීරණය වන්නේ ප්‍රධාන වශයෙන් කාගෙන් ලැබෙන ජන්මාණුව මතද?", "පියාගෙන් ලැබෙන ශුක්‍රාණුව මත", "මවගෙන් ලැබෙන ඩිම්බය මත", "ආහාර රටාව මත", "පරිසර උෂ්ණත්වය මත", "X හෝ Y වර්ණදේහය දරන ශුක්‍රාණුව ඩිම්බය හා එක් වීම මත ලිංගය තීරණය වේ."),
    q("හිමොෆීලියාව සහ රතු-කොළ වර්ණ අන්ධතාව යන ආවේණික රෝග හැඳින්වෙන්නේ කුමන නමින්ද?", "X-ප්‍රතිබද්ධ (ලිංග ප්‍රතිබද්ධ) නිලීන රෝග", "අලිංගික ප්‍රමුඛ රෝග", "බෝවන රෝග", "විටමින් ඌනතා රෝග", "මෙම රෝග ජාන X වර්ණදේහයේ පිහිටා ඇති බැවින් පිරිමින් අතර බහුලය."),
    q("රුධිරය කැටි නොගැසීමේ ජානමය රෝගී තත්ත්වය හඳුන්වන්නේ කුමන නමින්ද?", "හිමොෆීලියාව", "තැලසීමියාව", "නීරක්තිය", "ලියුකේමියාව", "හිමොෆීලියාව X-ප්‍රතිබද්ධ නිලීන ජානයක් නිසා හටගනී."),
    q("හිමොග්ලොබින් නිපදවීම අඩු වී රතු රුධිරාණු ඉක්මනින් බිඳ වැටෙන අලිංගික නිලීන ජානමය රෝගය කුමක්ද?", "තැලසීමියාව", "හිමොෆීලියාව", "වර්ණ අන්ධතාව", "ඩෙංගු", "විවාහයට පෙර රුධිර පරීක්ෂාවෙන් තැලසීමියා වාහකයන් හඳුනා ගත හැක."),
    q("ඩවුන් සින්ඩ්‍රෝමය (Down's syndrome) ඇති වීමට හේතු වන වර්ණදේහ විකෘතිය කුමක්ද?", "21 වන වර්ණදේහ යුගලයේ අමතර වර්ණදේහයක් තිබීම (මුළු ගණන 47)", "වර්ණදේහ සංඛ්‍යාව 45 වීම", "X වර්ණදේහයක් අඩු වීම", "DNA සම්පූර්ණයෙන් නැති වීම", "මෙය ට්‍රයිසොමි-21 ලෙස ද හැඳින්වේ."),
    q("ජාන තාක්ෂණයේදී එක් ජීවියෙකුගේ ප්‍රයෝජනවත් ජානයක් තවත් ජීවියෙකුගේ DNA තුළට ඇතුළු කිරීමෙන් නිපදවන ජීවීන් කවුද?", "ජාන විකරණය කළ ජීවීන් (GMO)", "දෙමුහුන් ජීවීන්", "සමයුග්මක ජීවීන්", "සංක්‍රාන්ති ලෝහ", "බැක්ටීරියා තුළ මිනිස් ඉන්සියුලින් නිපදවීම මීට උදාහරණයකි."),
    q("දියවැඩියා රෝගීන්ට අවශ්‍ය මිනිස් ඉන්සියුලින් හෝමෝනය මහා පරිමාණයෙන් නිපදවීමට ජාන ඉංජිනේරු විද්‍යාවේදී යොදා ගන්නා ක්ෂුද්‍රජීවියා කවුද?", "E. coli බැක්ටීරියාව", "මැලේරියා පරපෝෂිතයා", "ඩෙංගු වෛරසය", "පෙනිසිලියම් දිලීරය", "මිනිස් ඉන්සියුලින් ජානය බැක්ටීරියා ප්ලාස්මිඩයකට බද්ධ කෙරේ."),
    q("කෘත්‍රිමව නොවූ ස්වාභාවික ජීවී සමූහයක පවතින ජානමය වෙනස්කම් නව ප්‍රභේද බිහි වීමට හේතු වන ආකාරය විස්තර කරන චාල්ස් ඩාවින්ගේ සිද්ධාන්තය කුමක්ද?", "ස්වාභාවික වරණ වාදය", "සෛල වාදය", "විකිරණ වාදය", "මෙන්ඩල් වාදය", "පරිසරයට වඩාත් හොඳින් අනුවර්තනය වූ ජීවීන් නොනැසී පැවතී ප්‍රජනනය කරයි."),
    q("ප්‍රවේණික ද්‍රව්‍යයේ (DNA) හදිසි හා ස්ථිර වෙනස්වීමක් සිදුවීම හඳුන්වන්නේ කුමන නමින්ද?", "විකෘතිය (Mutation)", "සංසේචනය", "අනූනනය", "ප්‍රතිවලිත වීම", "X-කිරණ, UV කිරණ හා සමහර රසායනික ද්‍රව්‍ය විකෘති ඇති කරයි."),
    q("රසායනාගාරයේදී බැක්ටීරියා හා දිලීර වගා කිරීමට පෙර රෝපණ මාධ්‍යය හා උපකරණ ජීවානුහරණය කිරීමට යොදන උපකරණය කුමක්ද?", "ඕටෝක්ලේව් යන්ත්‍රය (Autoclave)", "කේන්ද්‍රාපසාරකය", "වර්ණමානය", "පෝටෝමීටරය", "121°C උෂ්ණත්වයේ අධි පීඩන හුමාලයෙන් සියලු ක්ෂුද්‍රජීවීන් විනාශ වේ."),
    q("පොල් රා විනාකිරි බවට පත් කිරීමේදී මුලින්ම සීනි එතනෝල් බවට පැසවන්නේ කුමන ක්ෂුද්‍රජීවියාද?", "යීස්ට්", "ඇසිටොබැක්ටර්", "ලැක්ටොබැසිලස්", "රයිසෝබියම්", "පසුව ඇසිටොබැක්ටර් බැක්ටීරියාව එතනෝල් ඇසිටික් අම්ලය බවට ඔක්සිකරණය කරයි."),
    q("කිරිවල ඇති ලැක්ටෝස් සීනි ලැක්ටික් අම්ලය බවට හරවා යෝගට් හා මුදවපු කිරි නිපදවන බැක්ටීරියාව කුමක්ද?", "ලැක්ටොබැසිලස්", "රයිසෝබියම්", "සැල්මොනෙල්ලා", "ක්ලොස්ට්‍රිඩියම්", "ලැක්ටික් අම්ලය කිරි ප්‍රෝටීන කැටි ගැස්වීමට හේතු වේ."),
    q("කෙඳි නිස්සාරණය (පොල් ලෙලි පල් කිරීම) සඳහා උපකාරී වන ජෛව ක්‍රියාවලිය සිදු කරන්නේ කුමක් මඟින්ද?", "බැක්ටීරියා", "ඇල්ගී", "වෛරස", "ප්‍රොටොසෝවා", "බැක්ටීරියා මගින් කොහු අතර ඇති පෙක්ටීන් ජීර්ණය කර කෙඳි වෙන් කරයි."),
    q("මළ ශාක හා සත්ව දේහ දිරාපත් කර පසට ඛනිජ ලවණ නැවත එක් කරන පරිසරයේ 'වියෝජකයන්' කවුද?", "බැක්ටීරියා සහ දිලීර", "හරිත ශාක", "ශාක භක්ෂකයන්", "මාංස භක්ෂකයන්", "වියෝජකයන් නොමැති නම් පෝෂක චක්‍රීකරණය නවතී."),
    q("පරිසර පද්ධතියක නිෂ්පාදකයාගේ සිට ඉහළ පෝෂී මට්ටම් කරා ගලා යන මූලික දෙය කුමක්ද?", "ශක්තිය", "මුදල්", "පාෂාණ", "චුම්භකත්වය", "පරිසර පද්ධති තුළ ශක්තිය එක් දිශාවකට ගලා යන අතර පදාර්ථ චක්‍රීකරණය වේ."),
    q("ආහාර දාමයක එක් පෝෂී මට්ටමක සිට ඊළඟ පෝෂී මට්ටමට සාමාන්‍යයෙන් සම්ප්‍රේෂණය වන ශක්ති ප්‍රතිශතය කොපමණද?", "10% පමණ", "90% පමණ", "100% ක්", "50% පමණ", "ඉතිරි 90% ශ්වසනය, තාපය හා බහිස්ස්‍රාවය ලෙස පරිසරයට එක් වේ."),
    q("ඕනෑම ස්වාභාවික පරිසර පද්ධතියක බොහෝ විට ආහාර දාමයක පෝෂී මට්ටම් 4–5 කට සීමා වීමට ප්‍රධාන හේතුව කුමක්ද?", "සෑම පියවරකදීම විශාල ශක්ති ප්‍රමාණයක් අපතේ යාම", "සතුන්ගේ සංඛ්‍යාව අධික වීම", "ජලය හිඟ වීම", "හිරු එළිය වැඩි වීම", "ඉහළ මට්ටම්වලට ඉතිරි වන ශක්තිය ඉතා අල්ප බැවිනි."),
    q("කිසිවිටෙකත් උඩුකුරු නොවන, සෑම පරිසර පද්ධතියකම සෘජු පිරමීඩයක් ලෙසම පවතින පාරිසරික පිරමීඩය කුමක්ද?", "ශක්ති පිරමීඩය", "සංඛ්‍යා පිරමීඩය", "ජෛව ස්කන්ධ පිරමීඩය", "පරිමා පිරමීඩය", "තනි විශාල ගසක සංඛ්‍යා පිරමීඩය උඩුකුරු විය හැකි නමුත් ශක්ති පිරමීඩය සැමවිටම සෘජුය."),
    q("පරිසරයේ ජලභූ-රසායනික චක්‍ර අතුරින් වායුගෝලීය නයිට්‍රජන් (N₂) පසේ නයිට්‍රේට බවට පත් කරන ක්‍රියාවලිය කුමක්ද?", "නයිට්‍රජන් තිර කිරීම", "විනයිට්‍රීකරණය", "උත්ස්වේදනය", "ප්‍රභාසංස්ලේෂණය", "අකුණු ගැසීම් හා නයිට්‍රජන් තිර කරන බැක්ටීරියා මඟින් මෙය සිදුවේ."),
    q("පසේ ඇති නයිට්‍රේට නැවත වායුගෝලීය නයිට්‍රජන් වායුව (N₂) බවට හරවා පස නිසරු කරන බැක්ටීරියා ක්‍රියාව කුමක්ද?", "විනයිට්‍රීකරණය", "නයිට්‍රීකරණය", "ඇමෝනීකරණය", "නයිට්‍රජන් තිර කිරීම", "සූඩොමොනාස් වැනි නිර්වායු බැක්ටීරියා ජලය පිරුණු පස්වල මෙය සිදු කරයි."),
    q("කාබන් චක්‍රයේදී වායුගෝලයෙන් කාබන් ඩයොක්සයිඩ් ඉවත් කරන ප්‍රධානම ජීව විද්‍යාත්මක ක්‍රියාවලිය කුමක්ද?", "ප්‍රභාසංස්ලේෂණය", "ශ්වසනය", "දහනය", "වියෝජනය", "ප්‍රභාසංස්ලේෂණය ගෝලීය CO₂ සමතුලිතතාව රැකීමට ඉතා වැදගත් වේ."),
    q("ගෝලීය උණුසුම ඉහළ යාමට ප්‍රධාන වශයෙන්ම හේතු වන හරිතාගාර වායුව කුමක්ද?", "කාබන් ඩයොක්සයිඩ් (CO₂)", "ඔක්සිජන් (O₂)", "නයිට්‍රජන් (N₂)", "ආගන් (Ar)", "ෆොසිල ඉන්ධන දහනය හා වන විනාශය CO₂ සාන්ද්‍රණය ඉහළ දමයි."),
    q("වායුගෝලයේ අහිතකර පාරජම්බුල කිරණවලින් පෘථිවිය ආරක්ෂා කරන ස්ථරය වන ඕසෝන් (O₃) ස්තරය ක්ෂය වීමට ප්‍රධාන හේතුව කුමක්ද?", "ක්ලෝරෝෆ්ලෝරෝකාබන් (CFC) වායු", "ඔක්සිජන් වායුව", "හයිඩ්‍රජන් වායුව", "ජල වාෂ්ප", "ශීතකරණ හා වායුසමීකරණවල CFC වෙනුවට පරිසර හිතකාමී වායු දැන් යොදා ගනී."),
    q("කර්මාන්තශාලා හා වාහනවලින් පිටවන SO₂ සහ NO₂ වායු වැසි ජලයේ දිය වීමෙන් ඇතිවන පාරිසරික ගැටලුව කුමක්ද?", "අම්ල වැසි", "ඕසෝන් සිදුර", "සුපෝෂණය", "ජෛව සාන්ද්‍රණය", "අම්ල වැසි ජලජ ජීවීන්ට, වනාන්තරවලට හා කිරිගරුඬ ගොඩනැගිලිවලට හානි කරයි."),
    q("රසායනික පොහොර ජලාශවලට සේදී යාමෙන් ඇල්ගී අධිකව වර්ධනය වී ජලයේ ඔක්සිජන් අඩු වී මසුන් මිය යාම කුමක්ද?", "සුපෝෂණය (Eutrophication)", "ජෛව විවිධත්වය", "ප්‍රකාශවර්තනය", "හරිතාගාර ආචරණය", "නයිට්‍රේට් හා පොස්පේට් අයන වැඩිවීම ඇල්ගී පිපීමට හේතු වේ."),
    q("ආහාර දාමයක් ඔස්සේ ඉහළ පෝෂී මට්ටම් වෙත යන විට නොදිරන බැර ලෝහ හා කෘමිනාශක (උදා: DDT) සාන්ද්‍රණය වැඩි වීම කුමක්ද?", "ජෛව සාන්ද්‍රණය (Biomagnification)", "වියෝජනය", "සුපෝෂණය", "සමස්ථිතිය", "මේවා ජීවී පටකවල මේද තුළ තැන්පත් වී ඉහළම විලෝපිකයාට දැඩිව බලපායි."),
    q("එක් විශේෂයකට ප්‍රයෝජන ලැබෙන අතර අනෙක් විශේෂයට හානියක් හෝ වාසියක් සිදු නොවන අන්තර් ක්‍රියාව කුමක්ද?", "සහභෝජීතාව (Commensalism)", "අන්‍යෝන්‍යාධාරය", "පරපෝෂීතාව", "විලෝපිකතාව", "ගසක් මත වැඩෙන උඩවැඩියා (ඕකිඩ්) ශාකය සහභෝජීතාවට උදාහරණයකි."),
    q("සහභාගී වන ජීවී විශේෂ දෙකටම අන්‍යෝන්‍ය වශයෙන් වාසි සැලසෙන ජෛව සම්බන්ධතාව කුමක්ද?", "අන්‍යෝන්‍යාධාරය (Mutualism)", "පරපෝෂීතාව", "තරගය", "සහභෝජීතාව", "මීමැස්සා හා සපුෂ්ප ශාක අතර සබඳතාව අන්‍යෝන්‍යාධාරයකි."),
    q("ඒක-වර්ණ හෝ ප්ලාස්ටික් අපද්‍රව්‍ය කළමනාකරණයේ 4R සංකල්පයේ නොමැති පියවර කුමක්ද?", "දහනය කිරීම (Burn)", "ප්‍රතික්ෂේප කිරීම (Refuse)", "අවම කිරීම (Reduce)", "ප්‍රතිචක්‍රීකරණය (Recycle)", "4R යනු Refuse, Reduce, Reuse, Recycle යන්නයි."),
    q("ශ්‍රී ලංකාවේ නිරිතදිග කලාපයේ පිහිටි ලෝක උරුම නිවර්තන වැසි වනාන්තරය කුමක්ද?", "සිංහරාජ වනාන්තරය", "යාල වනෝද්‍යානය", "විල්පත්තු වනෝද්‍යානය", "හෝර්ටන් තැන්න", "සිංහරාජය ඉහළ ආවේණිකත්වයක් සහිත ජෛව විවිධත්ව මධ්‍යස්ථානයකි."),
    q("එක් ස්වාභාවික ප්‍රදේශයකට පමණක් සීමා වූ ලොව වෙනත් කිසිදු තැනක ස්වාභාවිකව හමු නොවන ජීවී විශේෂ කවුද?", "ආවේණික විශේෂ (Endemic species)", "විදේශීය විශේෂ", "ආක්‍රමණික විශේෂ", "දේශීය විශේෂ", "දේශීය විශේෂ වෙනත් රටවල ද ස්වාභාවිකව සිටිය හැකි නමුත් ආවේණික විශේෂ එක් රටකට පමණි."),
    q("කඩොලාන පරිසර පද්ධති සංරක්ෂණය කිරීමේ ප්‍රධාන පාරිසරික වැදගත්කමක් වන්නේ කුමක්ද?", "වෙරළ ඛාදනය වැළැක්වීම හා මත්ස්‍ය පැටවුන්ට රැකවරණය දීම", "ලුණු නිෂ්පාදනය වැඩි කිරීම", "මිරිදිය උල්පත් වියළීම", "තෙත් බිම් ගොඩ කිරීම", "කඩොලාන සුනාමි වැනි රළ පහරවල බලය අඩු කරයි."),
    q("පහත සඳහන් ජෛව සමූහ අතරින් 'ජනගහනයක්' (Population) නිවැරදිව නිරූපණය කරන්නේ කුමක්ද?", "නිශ්චිත කාලයකදී එකම ප්‍රදේශයක වෙසෙන එකම විශේෂයේ ජීවීන් සමූහය", "වනයක සිටින සියලුම සතුන් හා ගස්", "පෘථිවියේ සියලුම ජීවීන් හා අජීවී පරිසරය", "තනි අලියෙක්", "ජනගහන කිහිපයක් එක්ව ප්‍රජාවක් සාදයි."),
    q("කිසියම් ජනගහනයක සිග්මොයිඩ (S-හැඩැති) වර්ධන වක්‍රයේ ස්ථායී අවධියේදී (උපරිම ධාරිතාවේදී) සිදු වන්නේ කුමක්ද?", "උපත් සංඛ්‍යාව මරණ සංඛ්‍යාවට ආසන්න වශයෙන් සමාන වීම", "ජනගහනය ශීඝ්‍රයෙන් ශුන්‍ය වීම", "උපත් සීඝ්‍රතාව අසීමිතව වැඩි වීම", "ආහාර අසීමිතව වැඩි වීම", "පරිසරයේ ධාරණ ධාරිතාවට ළඟා වූ විට වර්ධනය නියත වේ."),
    q("වී වගාවට හානි කරන පළිබෝධකයන් මර්දනය සඳහා ස්වාභාවික විලෝපිකයන් (උදා: ගෙම්බන්, බත්කූරන්) යොදා ගැනීම කුමක්ද?", "ජෛව විද්‍යාත්මක පාලනය", "රසායනික පාලනය", "යාන්ත්‍රික පාලනය", "විකිරණ පාලනය", "පරිසර හිතකාමී හා තිරසාර පළිබෝධ පාලන ක්‍රමයකි."),
    q("ප්‍රතිදේහ මඟින් පාලනය කළ නොහැකි නමුත් පසුගිය වසරවල භාවිත කළ ආහාර පරිරක්ෂණයක් වන පැස්ටරීකරණය හඳුන්වා දුන් විද්‍යාඥයා කවුද?", "ලුවී පාස්චර්", "ග්‍රෙගර් මෙන්ඩල්", "රොබට් හුක්", "චාල්ස් ඩාවින්", "කිරි 72°C දී තත්පර 15 ක් රත් කර ක්ෂණිකව සිසිල් කිරීමෙන් රෝග කාරක නැසේ."),
    q("DNA වල අඩංගු ජානමය තොරතුරු ප්‍රෝටීනයක් බවට පරිවර්තනය කිරීමේදී පණිවිඩ රැගෙන යන න්‍යෂ්ටික අම්ලය කුමක්ද?", "mRNA (පණිවුඩකාරක RNA)", "ATP", "ග්ලයිකෝජන්", "හිමොග්ලොබින්", "mRNA න්‍යෂ්ටියේ සිට සෛල ප්ලාස්මයේ රයිබොසෝම වෙත කේත ගෙන යයි."),
    q("දෙමව්පියන් දෙදෙනාම විෂමයුග්මක (Tt) වන විට ලැබෙන දරුවෙකු සමයුග්මක නිලීන (tt) වීමේ සම්භාවිතාව කොපමණද?", "25% (1/4)", "50% (1/2)", "75% (3/4)", "100%", "TT : Tt : tt අනුපාතය 1 : 2 : 1 බැවින් tt ලැබීමේ සම්භාවිතාව 1/4 කි."),
    q("ජලය හරහා ව්‍යාප්ත වන බැක්ටීරියා රෝගයකට උදාහරණයක් වන්නේ කුමක්ද?", "කොලරාව සහ උණ සන්නිපාතය", "ඩෙංගු", "මැලේරියාව", "ජලභීතිකාව", "අපිරිසිදු පානීය ජලයෙන් කොලරාව වැළඳේ."),
    q("වායුගෝලයේ හරිතාගාර ආචරණය නොතිබුණහොත් පෘථිවි මතුපිටට සිදුවන්නේ කුමක්ද?", "පෘථිවිය ජීවීන්ට වාසය කළ නොහැකි තරමට ඉතා සීතල වීම (-18°C පමණ)", "පෘථිවිය උණු වී යාම", "සාගර වාෂ්ප වී යාම", "වායුගෝලය ඉවත් වීම", "ස්වාභාවික හරිතාගාර ආචරණය ජීවයට හිතකර උෂ්ණත්වය රැක දෙයි."),
    q("දැව කර්මාන්තයේදී හා දුම්කොළ වැනි කර්මාන්තවලදී ආහාර ද්‍රව්‍ය නරක් වීමට බලපාන විෂ නිපදවන ඇස්පර්ජිලස් දිලීරය නිපදවන විෂ කුමක්ද?", "ඇෆ්ලාටොක්සින් (Aflatoxin)", "ඉන්සියුලින්", "පෙනිසිලින්", "ටයලින්", "තෙත් හා උණුසුම් තත්ත්වවල ගබඩා කළ රටකජු හා බඩඉරිඟුවල මෙය වැඩේ."),
    q("ශ්‍රී ලංකාවේ බහුලව දැකිය හැකි ආක්‍රමණික ආගන්තුක ජලජ ශාකයකට උදාහරණයක් වන්නේ කුමක්ද?", "ජපන් ජබර හා සැල්වීනියා", "නෙළුම්", "මානෙල්", "කෙකටිය", "මෙම ශාක ජලාශ වැසී ස්වදේශික ජලජ ජීවීන්ට හානි කරයි."),
    q("ආහාර දාමයක 'තෘතීයික පාරිභෝගිකයා' සාමාන්‍යයෙන් කුමන පෝෂණ කාණ්ඩයකට අයත් වේද?", "ඉහළ මාංස භක්ෂකයන් (උදා: උකුස්සා)", "හරිත ශාක", "ශාක භක්ෂකයන්", "ප්‍රාථමික නිෂ්පාදකයන්", "නිෂ්පාදක → ප්‍රාථමික (ශාක භක්ෂක) → ද්විතීයික → තෘතීයික."),
    q("පරිසර හිතකාමී තිරසාර කෘෂිකර්මාන්තයේදී රසායනික පොහොර වෙනුවට භාවිත කළ හැකි හොඳම විකල්පය කුමක්ද?", "කොම්පෝස්ට් හා කාබනික පොහොර", "ප්ලාස්ටික් අළු", "රසදිය ලවණ", "බැර ලෝහ ද්‍රාවණ", "කාබනික පොහොර පසේ ජල රඳවා ගැනීමේ හැකියාව හා ක්ෂුද්‍රජීවී ක්‍රියාව වැඩි කරයි."),
    q("කිසියම් ජීවී විශේෂයක ආරක්ෂාව සඳහා ඔවුන්ගේ ස්වාභාවික වාසස්ථාන තුළම සංරක්ෂණය කිරීම කුමක්ද?", "ස්ථානීය සංරක්ෂණය (In-situ conservation)", "බාහිර සංරක්ෂණය (Ex-situ)", "පටක රෝපණය", "බීජ බැංකු", "ජාතික වනෝද්‍යාන හා අභයභූමි ස්ථානීය සංරක්ෂණයට උදාහරණ වේ."),
    q("සත්වෝද්‍යාන, උද්භිද උද්‍යාන හා බීජ බැංකු මඟින් වඳවීමේ තර්ජනයට ලක් වූ ජීවීන් රැක ගැනීම කුමන සංරක්ෂණ ක්‍රමයක්ද?", "බාහිර සංරක්ෂණය (Ex-situ conservation)", "ස්ථානීය සංරක්ෂණය", "රසායනික පාලනය", "ජෛව සාන්ද්‍රණය", "සතුන් හා ශාක ඔවුන්ගේ ස්වාභාවික පරිසරයෙන් පිටත ආරක්ෂිතව තබා ගනී."),
    q("එකම සංසේචිත යුක්තාණුවක් මුල් අවධියේදී කොටස් දෙකකට වෙන් වී බිහිවන නිවුන් දරුවන්ගේ ප්‍රවේණික ලක්ෂණ කෙබඳුද?", "සම්පූර්ණයෙන්ම සමාන ජාන හා සමාන ලිංගිකත්වය ඇත", "සෑම විටම ලිංගිකත්වය වෙනස් වේ", "ජාන සම්පූර්ණයෙන් වෙනස් වේ", "වර්ණදේහ ගණන අඩු වේ", "මොවුන් සමරූපී නිවුන් දරුවන් (Identical twins) ලෙස හැඳින්වේ."),
    q("රසායනාගාරයේදී පැළවීමේදී ඒකාකාර පැළ බිහි කරන වර්ධක ප්‍රචාරණයට සාපේක්ෂව ලිංගික ප්‍රජනනයේ ප්‍රධාන වාසිය කුමක්ද?", "ප්‍රවේණික විවිධත්වය ඇති වී පරිසර වෙනස්වීම්වලට ඔරොත්තු දීම", "සර්වසම දරුවන් ලැබීම", "එක් ජීවියෙකු පමණක් ප්‍රමාණවත් වීම", "කෙටි කාලයකින් අස්වැන්න ලැබීම", "නව ජාන සංයෝජන පරිණාමයට අත්‍යවශ්‍ය වේ."),
    q("මිනිසාගේ රුධිර කාණ්ඩ නියාමනය කරන ABO ජානයේ ඇති ඇලීල සංඛ්‍යාව කීයද?", "3 (Iᴬ, Iᴮ, i)", "2 (A, B)", "4", "1", "පුද්ගලයෙකු තුළ ඕනෑම අවස්ථාවක ඉන් ඇලීල දෙකක් පවතී (බහු-ඇලීල)."),
    q("O රුධිර කාණ්ඩය ඇති පුද්ගලයෙකුගේ ප්‍රවේණිදර්ශය (Genotype) කෙබඳුද?", "ii", "IᴬIᴬ", "Iᴬi", "Iᴮi", "i ඇලීලය නිලීන බැවින් O රුධිර කාණ්ඩය ලැබීමට ii ලෙස පැවතිය යුතුය."),
    q("දෙමව්පියන්ගෙන් එක් අයෙකු AB රුධිර කාණ්ඩය ද අනෙකා O රුධිර කාණ්ඩය ද නම්, දරුවන්ට ලැබිය හැකි රුධිර කාණ්ඩ මොනවාද?", "A හෝ B පමණි", "AB හෝ O පමණි", "O පමණි", "A, B, AB සහ O සියල්ල", "IᴬIᴮ × ii මුහුමෙන් Iᴬi (A) සහ Iᴮi (B) ප්‍රවේණිදර්ශ පමණක් ලැබේ."),
    q("මිනිසාගේ සෑම සාමාන්‍ය ශුක්‍රාණුවකම හෝ ඩිම්බයකම අඩංගු වර්ණදේහ සංඛ්‍යාව කීයද?", "23", "46", "22", "44", "ජන්මාණු ඒකගුණ (n = 23) වන අතර දේහ සෛල ද්විගුණ (2n = 46) වේ."),
    q("පවුල් ගසක් හෝ ප්‍රවේණික ලක්ෂණයක් පරම්පරා ගණනාවක් ඔස්සේ සම්ප්‍රේෂණය වන ආකාරය පෙන්වන සටහන කුමක්ද?", "පෙළපත් සටහන (Pedigree chart)", "පිරමීඩ සටහන", "හරස්කඩ සටහන", "දණ්ඩ ප්‍රස්තාරය", "පෙළපත් සටහන් ආවේණික රෝග පරීක්ෂා කිරීමේදී යොදා ගනී."),
    q("සංකරණය හෙවත් මුහුම් කිරීමේදී නිලීන ලක්ෂණයක් පළමු පරම්පරාවේ (F₁) සැඟවී සිට නැවත දෙවන පරම්පරාවේ (F₂) ප්‍රකාශ වීමට හේතුව කුමක්ද?", "ප්‍රමුඛ ඇලීලය ඉදිරියේ නිලීන ඇලීලය යටපත් වීම", "නිලීන ජානය විනාශ වීම", "වර්ණදේහ බෙදීම නැවතීම", "විකෘතියක් සිදුවීම", "විෂමයුග්මක අවස්ථාවේදී නිලීන ඇලීලය නොනැසී පවතී."),
    q("රනුන්කියුලස් වෙනුවට ගෙවතු මෑ ශාකය (Pisum sativum) මෙන්ඩල් තෝරා ගැනීමට හේතුවූ වැදගත් ලක්ෂණයක් නොවන්නේ කුමක්ද?", "බහුවාර්ෂික විශාල ගසක් වීම", "කෙටි ජීවන චක්‍රයක් තිබීම", "පහසුවෙන් ස්වපරාගණය හා පරපරාගණය කළ හැකි වීම", "පැහැදිලි විරුද්ධ ලක්ෂණ පැවතීම", "මෑ ශාකය කෙටි කලකින් අස්වැන්න දෙන වාර්ෂික ශාකයකි."),
    q("මිනිස් ශරීරයේ අසාත්මිකතා හෝ ආසාදනවලට එරෙහිව භාවිත කරන පෙනිසිලින් ප්‍රතිජීවකය නිපදවන ක්ෂුද්‍රජීවියා කුමන කාණ්ඩයට අයත්ද?", "දිලීර (Penicillium notatum)", "බැක්ටීරියා", "වෛරස", "ප්‍රොටොසෝවා", "ඇලෙක්සැන්ඩර් ෆ්ලෙමින් විසින් පෙනිසිලියම් දිලීරයෙන් පෙනිසිලින් සොයා ගත්තේය."),
    q("ප්‍රතිජීවක ඖෂධ ක්‍රියාත්මක නොවන්නේ පහත සඳහන් කුමන රෝග කාරකයන්ට එරෙහිවද?", "වෛරස (උදා: ඩෙංගු, සෙම්ප්‍රතිශ්‍යාව)", "බැක්ටීරියා (උදා: ක්ෂය රෝගය)", "සමහර දිලීර", "ඇතැම් ප්‍රොටොසෝවාවන්", "වෛරසවලට සෛල බිත්ති හෝ බැක්ටීරියා රයිබොසෝම නොමැති නිසා ප්‍රතිජීවක අසාර්ථක වේ."),
    q("රෝග වැළැක්වීම සඳහා දුර්වල කළ හෝ මරා දැමූ රෝග කාරක ශරීරගත කිරීමේ ක්‍රියාවලිය කුමක්ද?", "එන්නත්කරණය (Vaccination)", "විෂබීජහරණය", "පැස්ටරීකරණය", "ප්‍රතිදේහ විනාශය", "එන්නත් මඟින් ශරීරය තුළ කෘත්‍රිම සක්‍රීය ප්‍රතිශක්තිය ගොඩනගයි."),
    q("බැක්ටීරියා, දිලීර හා වෛරස ආදී ක්ෂුද්‍රජීවීන් අතරින් ජීවී සෛලයකින් පිටත අජීවී ස්ඵටික ලෙස පවතින්නේ කුමන කාණ්ඩයද?", "වෛරස", "බැක්ටීරියා", "යීස්ට්", "ඇමීබා", "වෛරස ගුණනය වන්නේ ධාරක සෛලයක් තුළ පමණි."),
    q("සෛල බිත්තිය රහිත ඒකසෛලික යුකැරියෝටික ක්ෂුද්‍රජීවීන් අයත් වන ප්‍රධාන කාණ්ඩය කුමක්ද?", "ප්‍රොටොසෝවා (උදා: ඇමීබා, පැරමීසියම්)", "දිලීර", "බැක්ටීරියා", "වෛරස", "බොහෝ ප්‍රොටොසෝවාවන් ජලජ පරිසරවල පිහිනමින් ජීවත් වේ."),
    q("පාන් පිපීමේදී යීස්ට් නිර්වායු ශ්වසනයෙන් පිට කරන කුමන වායුව පාන් පිටි මෝලිය සිදුරු සහිතව පුම්බයිද?", "කාබන් ඩයොක්සයිඩ් (CO₂)", "ඔක්සිජන් (O₂)", "හයිඩ්‍රජන් (H₂)", "නයිට්‍රජන් (N₂)", "මධ්‍යසාර පැසීමේදී CO₂ වායුව සහ එතනෝල් නිපදවේ."),
    q("ප්‍රෝටීන බහුල මස්, මාළු වැනි ආහාර ක්ෂුද්‍රජීවීන් නිසා නරක් වී දුගඳ හැමීම හඳුන්වන්නේ කුමන නමින්ද?", "කුණුවීම (Putrefaction)", "පැසීම", "මුඩු වීම", "වාෂ්පීකරණය", "ප්‍රෝටීන වියෝජනයෙන් හයිඩ්‍රජන් සල්ෆයිඩ් හා ඇමෝනියා වැනි දුගඳ වායු සෑදේ."),
    q("තෙල් සහ මේද අඩංගු ආහාර ක්ෂුද්‍රජීවී එන්සයිම හා ඔක්සිජන් නිසා නරක් වී නරක රසක් ගැනීම කුමක්ද?", "මුඩු වීම (Rancidity)", "කුණුවීම", "පැසීම", "කැටි ගැසීම", "ලිපිඩ ජලවිච්ඡේදනය හා ඔක්සිකරණය මුඩු වීමට හේතු වේ."),
    q("රතු කැප්සියුල වැනි සුලභ රෝග කාරක වෛරසයක් වන HIV මඟින් ප්‍රධාන වශයෙන් විනාශ කරන්නේ කුමන සෛලද?", "සුදු රුධිරාණු (T-ලිම්ෆොසයිට)", "රතු රුධිරාණු", "රුධිර පට්ටිකා", "අස්ථි සෛල", "එමඟින් ශරීරයේ ප්‍රතිශක්තිකරණ පද්ධතිය දුර්වල වී AIDS තත්ත්වය ඇති වේ."),
    q("ද්විපද නාමකරණයට අනුව 'Oryza sativa' (වී) යන විද්‍යාත්මක නාමයේ 'Oryza' යන්නෙන් දැක්වෙන්නේ කුමක්ද?", "ගණ නාමය (Genus)", "විශේෂ නාමය (Species)", "කුලය", "රාජධානිය", "ගණ නාමය මුල් අකුර කැපිටල් වන අතර විශේෂ නාමය සිම්පල් අකුරින් ලියයි."),
    q("වීජගණිත නීති අනුව එකම වාසස්ථානයක ජීවත් වන එක් විශේෂයක ජීවීන් එම පරිසරයේ ඉටු කරන භූමිකාව හඳුන්වන්නේ කුමන නමින්ද?", "පාරිසරික නිකේතනය (Ecological niche)", "ආහාර දාමය", "ජෛව ගෝලය", "ජනගහන ඝනත්වය", "ජීවියෙකුගේ ආහාර ගැනීම, ප්‍රජනනය හා පරිසර අන්තර්ක්‍රියා නිකේතනයට අයත් වේ."),
    q("හිස් පාෂාණ මතුපිටක ලයිකන හා පාසි වලින් ආරම්භ වී ක්‍රමයෙන් වනාන්තරයක් දක්වා වෙනස් වීම කුමක්ද?", "ප්‍රාථමික පාරිසරික අනුක්‍රමණය", "ද්විතීයික අනුක්‍රමණය", "ජෛව සාන්ද්‍රණය", "සුපෝෂණය", "ගිනිගත් වනයක නැවත ගස් වැඩීම ද්විතීයික අනුක්‍රමණයයි."),
    q("පාරිසරික අනුක්‍රමණයේ අවසාන වශයෙන් ස්ථාපිත වන ස්ථාවර පරිසර පද්ධතිය හඳුන්වන්නේ කෙසේද?", "චරම ප්‍රජාව (Climax community)", "පුරෝගාමී ප්‍රජාව", "සංක්‍රාන්ති ප්‍රජාව", "වියෝජක ප්‍රජාව", "දේශගුණයට අනුරූපව දිගු කලක් සමතුලිතව පවතින අවධියයි."),
    q("ජලජ පරිසරයක ගැඹුර වැඩි වත්ම සූර්යාලෝකය අඩු වීම නිසා ජලජ ශාක සීමා වන අජීවී සාධකය කුමක්ද?", "ආලෝක තීව්‍රතාව", "සුළඟ", "පීඩනය පමණක්", "චුම්භක ක්ෂේත්‍රය", "ආලෝකය නොලැබෙන ගැඹුරු කලාපවල ප්‍රභාසංස්ලේෂණය සිදු නොවේ."),
    q("කිසියම් පරිසර පද්ධතියක ජීවීන්ගේ ව්‍යාප්තියට බලපාන 'අජීවී සාධකයක්' (Abiotic factor) වන්නේ කුමක්ද?", "උෂ්ණත්වය හා පසේ pH අගය", "විලෝපිකයන්", "පරපෝෂිතයන්", "වියෝජක බැක්ටීරියා", "ආලෝකය, ජලය, සුළඟ හා ඛනිජ ද අජීවී සාධක වේ."),
    q("වී වගාවේදී නිල්-හරිත ඇල්ගී (සයනොබැක්ටීරියා - උදා: Anabaena) කුඹුරු පස සරු කිරීමට දායක වන්නේ කෙසේද?", "වායුගෝලීය නයිට්‍රජන් තිර කිරීමෙන්", "කාබන් ඩයොක්සයිඩ් වැඩි කිරීමෙන්", "පස ආම්ලික කිරීමෙන්", "පොස්පරස් විනාශ කිරීමෙන්", "ඇසෝලා ජලජ පර්ණාංගය සමඟ සහජීවීව ජීවත් වෙමින් N₂ තිර කරයි."),
